#!/usr/bin/env python3
"""Build or verify the AI Trading Agent plugin from its canonical repository files.

This is an invoked packaging helper, not a runtime service. Run with --check in CI.
The generated directory is never used as the source of a skill update.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import stat


ROOT = Path(__file__).resolve().parents[2]
SKILL = Path('skills/ai-trading-agent')
DESTINATION = Path('plugins/ai-trading-agent')
MARKER = '<!-- Generated by .github/scripts/build_trading_plugin.py; edit canonical sources instead. -->'
ICONS = ('fictional-ticker.png', 'fictional-ticker-dark.png')


class BuildError(ValueError):
    pass


def checked_path(root: Path, relative: Path, *, directory: bool = False) -> Path:
    """Reject redirected or nonregular source/destination components before use."""
    if relative.is_absolute() or '..' in relative.parts:
        raise BuildError(f'Path must stay inside the repository: {relative}')
    path = root
    for part in (None, *relative.parts):
        if part is not None:
            path = path / part
        if not path.exists() and not path.is_symlink():
            continue
        info = path.lstat()
        if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & 0x400:
            raise BuildError(f'Symlink/reparse path is not allowed: {path}')
        if path != root / relative and not stat.S_ISDIR(info.st_mode):
            raise BuildError(f'Parent is not a directory: {path}')
    if path.exists() and not (path.is_dir() if directory else path.is_file()):
        raise BuildError(f'Unexpected file type: {path}')
    return path


def inventory(root: Path) -> tuple[dict[str, Path], set[str]]:
    files: dict[str, Path] = {}
    directories: set[str] = set()
    if not root.exists():
        return files, directories

    def onerror(error: OSError) -> None:
        raise error

    for current, child_directories, child_files in os.walk(root, topdown=True, followlinks=False, onerror=onerror):
        # Inspect directory entries before os.walk can descend into a reparse point.
        for name in sorted(child_directories + child_files):
            path = Path(current) / name
            relative = path.relative_to(root)
            info = path.lstat()
            if stat.S_ISLNK(info.st_mode) or getattr(info, 'st_file_attributes', 0) & 0x400:
                raise BuildError(f'Symlink/reparse path is not allowed: {path}')
            if stat.S_ISDIR(info.st_mode):
                directories.add(relative.as_posix())
            elif stat.S_ISREG(info.st_mode):
                files[relative.as_posix()] = path
            else:
                raise BuildError(f'Unexpected file type: {path}')
    return files, directories


def expected_files(root: Path) -> dict[str, bytes]:
    source = checked_path(root, SKILL, directory=True)
    if not source.is_dir():
        raise BuildError('Canonical AI Trading Agent skill is missing')
    source_files, _ = inventory(source)
    contents = {name: path.read_bytes() for name, path in source_files.items()}
    try:
        version = contents['VERSION'].decode('utf-8').strip()
        preservation = json.loads(contents['PACKAGE-MANIFEST.json'])
    except (KeyError, ValueError, UnicodeError) as exc:
        raise BuildError(f'Canonical skill version/manifest is invalid: {exc}') from exc
    hashes = preservation.get('files')
    if not isinstance(hashes, dict) or set(hashes) != set(contents) - {'PACKAGE-MANIFEST.json'}:
        raise BuildError('Canonical skill inventory differs from PACKAGE-MANIFEST.json')
    if preservation.get('version') != version:
        raise BuildError('Canonical skill manifest version differs from VERSION')
    for name, digest in hashes.items():
        if hashlib.sha256(contents[name]).hexdigest() != digest:
            raise BuildError(f'Canonical skill hash mismatch: {name}')

    manifest_path = checked_path(root, Path('docs/ai-trading-agent/plugin.json'))
    manifest_bytes = manifest_path.read_bytes()
    manifest = json.loads(manifest_bytes)
    if manifest.get('name') != 'ai-trading-agent':
        raise BuildError('Listing manifest must identify ai-trading-agent')
    if manifest.get('version') != version:
        raise BuildError('Listing manifest version differs from canonical skill VERSION')
    expected = {f'skills/ai-trading-agent/{name}': data for name, data in contents.items()}
    expected['plugin.json'] = manifest_bytes
    expected['LICENSE'] = checked_path(root, Path('LICENSE')).read_bytes()
    for icon in ICONS:
        expected[f'assets/{icon}'] = checked_path(root, Path('docs/ai-trading-agent/assets') / icon).read_bytes()
    expected['README.md'] = (f'{MARKER}\n\n# AI Trading Agent\n\n'
        f'Version {version}. This package contains the complete, self-contained AI Trading Agent skill.\n\n'
        'Read the [skill guide](./skills/ai-trading-agent/README.md), '
        '[installation prerequisites](./skills/ai-trading-agent/INSTALL.md), and '
        '[example prompts](./skills/ai-trading-agent/EXAMPLE-PROMPTS.md).\n\n'
        'The full skill includes research, paper analysis and host-dependent native broker handoff '
        'and execution instructions. Actual broker actions require supported host tools and user authority. '
        'Installing this package does not connect a broker or authorize trades.\n\n'
        'Python helpers run only when invoked in a permitted host environment with their prerequisites. '
        'No backend, daemon, MCP server or always-on service is bundled or required.\n\n'
        'This GitHub marketplace distribution is separate from approval or publication in the public '
        'OpenAI Directory. See the bundled [MIT license](./LICENSE).\n').encode('utf-8')
    return expected


def build(root: Path, *, check: bool) -> int:
    expected = expected_files(root)
    destination = checked_path(root, DESTINATION, directory=True)
    actual, actual_directories = inventory(destination)
    expected_directories = {parent.as_posix() for name in expected for parent in Path(name).parents
                            if parent != Path('.')}
    extra = sorted(set(actual) - set(expected))
    extra_directories = sorted(actual_directories - expected_directories)
    if extra or extra_directories:
        raise BuildError(f'Unexpected generated-directory contents; refusing to remove them: '
                         f'{extra + [name + "/" for name in extra_directories]}')
    missing = sorted(set(expected) - set(actual))
    changed = sorted(name for name in expected if name in actual and actual[name].read_bytes() != expected[name])
    if check:
        if missing or changed:
            raise BuildError(f'Generated plugin is stale: missing={missing}; changed={changed}')
    else:
        if actual:
            readme = actual.get('README.md')
            if readme is None or not readme.read_bytes().startswith((MARKER + '\n').encode('utf-8')):
                raise BuildError('Refusing to overwrite a pre-existing directory without the generator marker')
        destination.mkdir(parents=True, exist_ok=True)
        for name in missing + changed:
            path = checked_path(destination, Path(name))
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(expected[name])
    return len(expected)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true', help='Reject stale generated files without writing')
    args = parser.parse_args()
    try:
        count = build(ROOT, check=args.check)
    except (BuildError, OSError, ValueError) as exc:
        print(f'TRADING PLUGIN FAILED: {exc}')
        return 1
    print(f'TRADING PLUGIN {"CHECK PASSED" if args.check else "GENERATED"}: {count} files')
    return 0


if __name__ == '__main__':
    raise SystemExit(main())
